/** Signals that openpilot's ford_checksum() covers (fordcan.py FORD_CHECKSUM_FIELDS), for the IDs we use. */
export const CHECKSUM_FIELDS = {
  0x91: ['VehRol_W_Actl', 'VehYaw_W_Actl', 'VehRollYaw_No_Cnt', 'VehRolWActl_D_Qf', 'VehYawWActl_D_Qf'],
  0x202: ['Veh_V_ActlEng', 'VehVActlEng_No_Cnt', 'VehVActlEng_D_Qf'],
  0x415: ['Veh_V_ActlBrk', 'VehVActlBrk_No_Cnt', 'VehVActlBrk_D_Qf'],
};

export const messageById = (id) => MESSAGES.find((m) => m.id === id) || null;
export function signalByName(name) {
  for (const m of MESSAGES) { const s = m.signals.find((x) => x.name === name); if (s) return { ...s, message: m }; }
  return null;
}

